---@param idolLive3D_Camera_ table 
---@param baseJson_ table 
---@param freeCameraMotionBH_ table 
---@param freeVCam_ Cinemachine.CinemachineVirtualCamera   
---@param vcam2_  Cinemachine.CinemachineVirtualCamera   
function IdolLive3D_FreeCameraMgrV2:__init( idolLive3D_Camera_, baseJson_, freeCameraMotionBH_, freeVCam_, vcam2_ )
    assert( isNotNull(idolLive3D_Camera_) and isNotNull(baseJson_) )
    assert( isNotNull(freeCameraMotionBH_) )
    assert( isNotNull(freeVCam_) and isNotNull(vcam2_) )


    -- far plane 必须足够远, 否则无法看到天空盒
    local cameraParams = baseJson_.data.oths.cameraParams
    IdolLive3D_Utils.SetVCamNearFarClipPlane( freeVCam_,    cameraParams.nearPlane, cameraParams.farPlane )
    IdolLive3D_Utils.SetVCamNearFarClipPlane( vcam2_,       cameraParams.nearPlane, cameraParams.farPlane )

    ---
    self.idolLive3D_Camera = idolLive3D_Camera_
    self.idolLive3D_Main = idolLive3D_Camera_.idolLive3D_Main
    self.baseJson = baseJson_

    self.tgtPriority = IdolLive3D_States.VCamPriority.High

    

    -- =================
    self.idolLive3D_FreeCameraTrackNodeParamsManager_100 = idolLive3D_Camera_.idolLive3D_FreeCameraTrackNodeParamsManager_100
    self.idolLive3D_FreeCameraTrackNodeParamsManager_200 = idolLive3D_Camera_.idolLive3D_FreeCameraTrackNodeParamsManager_200


    -- 默认值:
    local initStage = self.baseJson.data.enterMgr.initStage
    local initIdleState = initStage.idleState
    local initFreeCameraTrackNodeParamsManager = initStage.freeTrackCamera.freeCameraTrackNodeParamsManager -- 就算是 PosLocked 相机, 这个实例也是拥有的


    assert(isNotNull( self.idolLive3D_Camera ))
    assert(isNotNull( initStage.freeTrackCamera.freeTrackCenterPos ))
    assert(isNotNull( self.idolLive3D_Camera.rawPoint ))
    assert(isNotNull( freeVCam_ ))
    assert(isNotNull( initFreeCameraTrackNodeParamsManager ))
    assert(isNotNull( initStage.freeTrackCamera.initCameraSpatialParams ))
    assert(isNotNull( initStage.freeTrackCamera.freeCameraActiveSpatialRange  ))

    -- ===
    ---@type IdolLive3D_FreeCameraMotion
    self.freeCameraMotion = IdolLive3D_Utils.GetLuaScr(freeCameraMotionBH_.gameObject, "Game.IdolLive3D.IdolLive3D_FreeCameraMotion" )
    self.freeCameraMotion:Init( 
        self.idolLive3D_Camera, 
        initStage.freeTrackCamera.freeTrackCenterPos, 
        self.idolLive3D_Camera.rawPoint, 
        freeVCam_, 
        initFreeCameraTrackNodeParamsManager, 
        initStage.freeTrackCamera.initCameraSpatialParams, 
        initStage.freeTrackCamera.freeCameraActiveSpatialRange
    )

    -- ===
    ---@type IdolLive3D_PosLockedCameraMotion
    self.posLockedCameraMotion = IdolLive3D_PosLockedCameraMotion.New( self.idolLive3D_Camera, self.baseJson, vcam2_ )

    ---
    self.freeCameraMotion:SetActive(true)
    self.posLockedCameraMotion:SetActive(true)

    -- ===
    self.freeCameraMode = nil -- 触发 SetFreeCameraMode() 被强制执行
    self:SetFreeCameraMode( initStage.freeCameraMode )

    --  
    -- !!! 设置初始 状态 
    -- ...
    
    ---
    self.isInit = true
end



-- 需手动调用 Delete()
function IdolLive3D_FreeCameraMgrV2:__delete()

    if isNotNull(self.posLockedCameraMotion) then 
        self.posLockedCameraMotion:Delete()
    end
end



----------------------------------------------------------

function IdolLive3D_FreeCameraMgrV2:SelfUpdate( deltaTime_ )
    if self.isInit ~= true then 
        return
    end 

    ---
    if self.freeCameraMode == FreeCameraMode.PosFree then 
        self.freeCameraMotion:SelfUpdate()
    elseif self.freeCameraMode == FreeCameraMode.PosLocked then 
        self.posLockedCameraMotion:SelfUpdate()
    else 
        printError("freeCameraMode 异常: " ..tostring(self.freeCameraMode))
    end 
end


----------------------------------------------------------


---@param isNotUseInitCameraSpatialParams_ boolean | nil
function IdolLive3D_FreeCameraMgrV2:SwitchFreeCamera_PosFree( freeTrackCenterPos_, freeCameraActiveSpatialRange_, initCameraSpatialParams_, freeCameraTrackNodeParamsManager_,
                                                            isNotUseInitCameraSpatialParams_ )
    self:SetFreeCameraMode( IdolLive3D_States.FreeCameraMode.PosFree )
    ---
    self:SetCenterPos( freeTrackCenterPos_ )
    self:ChangeFreeCameraTrackNodeParamsManager( freeCameraTrackNodeParamsManager_ )
    self:ChangeActiveSpatialRange( freeCameraActiveSpatialRange_ )
    ---
    if isNotNull(initCameraSpatialParams_) and isNotUseInitCameraSpatialParams_ ~= true then
        self:SetImmediately( initCameraSpatialParams_ )   
    end
end




function IdolLive3D_FreeCameraMgrV2:SwitchFreeCamera_PosLocked( posLockedCameraParams_ )
    self:SetFreeCameraMode( IdolLive3D_States.FreeCameraMode.PosLocked )
    self:SetImmediately( posLockedCameraParams_ ) -- 确保 posLockedCameraParams 里装配了对应的数据
    ---
    self:SetPosLockedModeParams(  posLockedCameraParams_ ) -- 确保 posLockedCameraParams 里装配了对应的数据
end




----------------------------------------------------------

function IdolLive3D_FreeCameraMgrV2:SetFreeCameraMode( freeCameraMode_ )
    assert( freeCameraMode_ == FreeCameraMode.PosFree or freeCameraMode_ == FreeCameraMode.PosLocked )
    if self.freeCameraMode == freeCameraMode_ then 
        print("已经是目标 freeCameraMode, 放弃切换, :" ..tostring(freeCameraMode_))
        return
    end 
    ---
    self.freeCameraMode = freeCameraMode_

    IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.Cut, 0 ) -- vcam 瞬切

    if freeCameraMode_ == FreeCameraMode.PosFree then 

        self.freeCameraMotion:SetPriority( self.tgtPriority )
        self.posLockedCameraMotion:SetPriority( IdolLive3D_States.VCamPriority.Low )

    elseif freeCameraMode_ == FreeCameraMode.PosLocked then 

        self.freeCameraMotion:SetPriority( IdolLive3D_States.VCamPriority.Low )
        self.posLockedCameraMotion:SetPriority( self.tgtPriority )

        self.posLockedCameraMotion:ResetImmediately()


    else 
        printError("参数 freeCameraMode 异常: " ..tostring(freeCameraMode_))
    end 
end



function IdolLive3D_FreeCameraMgrV2:GetFreeCameraMode()
    return self.freeCameraMode
end



-- ---@param params_ table
function IdolLive3D_FreeCameraMgrV2:SetPosLockedModeParams( params_ )

    if self.freeCameraMode == FreeCameraMode.PosFree then 
        printError("不该在此模式下调用")

    elseif self.freeCameraMode == FreeCameraMode.PosLocked then 
        self.posLockedCameraMotion:SetRangeParams( params_ ) -- posLockedCameraParams 
    else 
        printError("freeCameraMode 异常: " ..tostring(self.freeCameraMode))
    end 
end

----------------------------------------------------------


function IdolLive3D_FreeCameraMgrV2:SetPriority(priority_) 
    self.tgtPriority = checkNumber(priority_)

    if self.freeCameraMode == FreeCameraMode.PosFree then 
        self.freeCameraMotion:SetPriority( self.tgtPriority )

    elseif self.freeCameraMode == FreeCameraMode.PosLocked then 
        self.posLockedCameraMotion:SetPriority( self.tgtPriority )

    else 
        printError("freeCameraMode 异常: " ..tostring(self.freeCameraMode))
    end 
end


----------------------------------------------------------

---@param params_ table 
function IdolLive3D_FreeCameraMgrV2:SetImmediately( params_ )
    
    if self.freeCameraMode == FreeCameraMode.PosFree then 
        --printError("SetImmediately = PosFree")
        self.freeCameraMotion:SetImmediately( params_ ) -- initCameraSpatialParams_
    elseif self.freeCameraMode == FreeCameraMode.PosLocked then 
        --printError("SetImmediately = PosLocked")
        self.posLockedCameraMotion:SetImmediately( params_ ) -- posLockedCameraParams
    else 
        printError("freeCameraMode 异常: " ..tostring(self.freeCameraMode))
    end 
end



function IdolLive3D_FreeCameraMgrV2:SetSmooth( initCameraSpatialParams_ )
    self.freeCameraMotion:SetSmooth( initCameraSpatialParams_ )
end 



function IdolLive3D_FreeCameraMgrV2:SetCenterPos( centerPos_ )
    self.freeCameraMotion:SetCenterPos(centerPos_)
