function IdolLive3D_FreeCameraMgrV2:YawAndPitchByDelta( yawDelta_, pitchDelta_ )

    -- printError("yaw = " .. tostring(yawDelta_))
    -- printError("pitch = " .. tostring(pitchDelta_))

    if self.freeCameraMode == FreeCameraMode.PosFree then 

        --printError("poslocked yaw pitch")

        -- 一次只响应一个轴:
        if Mathf.Abs(yawDelta_) > Mathf.Abs(pitchDelta_) then 
            self.freeCameraMotion:YawByDelta( yawDelta_ )
        else 
            self.freeCameraMotion:PitchByDelta( pitchDelta_ )
        end 
    elseif self.freeCameraMode == FreeCameraMode.PosLocked then 

        --printError("freecamera")

        self.posLockedCameraMotion:YawByDelta( -yawDelta_ )
        self.posLockedCameraMotion:PitchByDelta( -pitchDelta_ )

    else 
        printError("freeCameraMode 异常: " ..tostring(self.freeCameraMode))
    end 
end




function IdolLive3D_FreeCameraMgrV2:ZoomByDelta( deltaPinch_ )

    if self.freeCameraMode == FreeCameraMode.PosFree then 
        self.freeCameraMotion:ZoomByDelta( deltaPinch_ )
    elseif self.freeCameraMode == FreeCameraMode.PosLocked then 
        self.posLockedCameraMotion:ZoomByDelta( deltaPinch_ )
    else 
        printError("freeCameraMode 异常: " ..tostring(self.freeCameraMode))
    end 
end



function IdolLive3D_FreeCameraMgrV2:FindClosestFreeCameraTrackNodeParams(pos_)
    return self.freeCameraMotion:FindClosestTrackNodeParams(pos_)
end





return IdolLive3D_FreeCameraMgrV2
